<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Diário Oficial - Abril 1930</title>
<style>
  body {
    font-family: "Times New Roman", Times, serif;
    font-size: 11px;
    line-height: 1.3;
    max-width: 900px;
    margin: 20px auto;
    padding: 10px;
    color: #1a1a1a;
  }
  .header {
    text-align: center;
    border-bottom: 2px solid #000;
    padding-bottom: 5px;
    margin-bottom: 10px;
  }
  .header-line {
    display: flex;
    justify-content: space-between;
    font-weight: bold;
    font-size: 12px;
  }
  .header-title {
    font-size: 16px;
    font-weight: bold;
    letter-spacing: 3px;
  }
  .columns {
    display: flex;
    gap: 20px;
  }
  .column {
    flex: 1;
    text-align: justify;
  }
  h2 {
    font-size: 13px;
